sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
        var sessionId = current.u_ai_session;
        if (!sessionId) return;

        // Count finished inferences in this session
        var countAgg = new GlideAggregate('u_ai_inference');
        countAgg.addQuery('u_ai_session', sessionId);
        countAgg.addQuery('u_state', 'finished');
        countAgg.addAggregate('COUNT');
        countAgg.query();

        var inferenceCount = 0;
        if (countAgg.next()) {
            inferenceCount = parseInt(countAgg.getAggregate('COUNT')); }

        // Only trigger on 4th, 8th, 12th, etc.
        if (inferenceCount % 4 !== 0) return;

        gs.info('AIAB: Triggering summary generation for session ' + sessionId + ' after ' + inferenceCount + ' inferences');

        // Get last 4 inferences to summarize
        var messages = [];
        var infGR = new GlideRecord('u_ai_inference');
        infGR.addQuery('u_ai_session', sessionId);
        infGR.addQuery('u_state', 'finished');
        infGR.orderByDesc('sys_created_on');
        infGR.setLimit(4);
        infGR.query();

        while (infGR.next()) {
            var prompt = infGR.getValue('u_prompt');
            var response = infGR.getValue('u_response');

            // Extract user message
            try {
                var parsed = JSON.parse(prompt);
                if (Array.isArray(parsed)) {
                    for (var i = parsed.length - 1; i >= 0; i--) {
                        if (parsed[i].role === 'user' && parsed[i].content) {
                            messages.unshift({role: 'user', content: parsed[i].content});
                            break;
                        }
                    }
                }
            } catch (e) {
                messages.unshift({role: 'user', content: prompt});
            }

            // Add assistant response
            if (response) {
                messages.unshift({role: 'assistant', content: response});
            }
        }

        messages.reverse();

        // Create summary inference (NOT linked to session - prevents loop)
        var summaryGR = new GlideRecord('u_ai_inference');
        summaryGR.initialize();
        summaryGR.u_type = 'generic';
        summaryGR.u_prompt = JSON.stringify([{
            role: 'system',
            content: 'Summarize this conversation briefly. What did the user want? What was done? What was the outcome? Max 200 words.'
        }, {
            role: 'user',
            content: 'Conversation to summarize:
' + JSON.stringify(messages, null, 2)
        }]);
        summaryGR.u_model = gs.getProperty('ai_in_a_box.config.server.llm.model') || 'gpt-4o-mini';
        summaryGR.u_requested_by = current.getValue('u_requested_by');
        summaryGR.u_state = 'new';
        // CRITICAL: No u_ai_session set - this prevents infinite loops
        var summaryId = summaryGR.insert();

        gs.info('AIAB: Created summary inference ' + summaryId + ' for session ' + sessionId);

    } catch (error) {
        gs.error('AIAB: Error triggering summary: ' + error);
    }
})(current, previous);
